static const uint8_t kYendor3Colon[FontGlyphSize] = {0x00, 0x20, 0x00, 0x00, 0x20, 0x00};
static const uint8_t kYendor3Semicolon[FontGlyphSize] = {0x00, 0x20, 0x00, 0x20, 0x40, 0x00};

const uint8_t *fontGlyph(GameKind game, unsigned font, unsigned ch) {
    if (font >= FontCount || ch < FontCharFirst || ch >= FontCharFirst + FontCharCount) {
        return NULL;
    }
    if (game == GameYendor3) {
        if (ch == ':') {
            return kYendor3Colon;
        }
        if (ch == ';') {
            return kYendor3Semicolon;
        }
    }
    return kGlyphs[font][ch - FontCharFirst];
}

int fontDrawChar(GameKind game, unsigned font, uint8_t *surface, size_t stride, int x, int y, unsigned ch, uint8_t foreground,
                 uint8_t background, FontBackground mode) {
    const uint8_t *glyph = fontGlyph(game, font, ch);
    if (glyph) {
        for (unsigned row = 0; row < FontHeight; row++) {
            uint8_t *line = surface + (size_t)(y + (int)row) * stride + (size_t)x;
            for (unsigned col = 0; col < FontAdvance; col++) {
                if (glyph[row] & (0x80 >> col)) {
                    line[col] = foreground;
                } else if (mode == FontOpaque) {
                    line[col] = background;
                }
            }
        }
    }
    return x + FontAdvance;
}

int fontDrawString(GameKind game, unsigned font, uint8_t *surface, size_t stride, int x, int y, const char *text, uint8_t foreground,
                   uint8_t background, FontBackground mode) {
    for (; *text; text++) {
        x = fontDrawChar(game, font, surface, stride, x, y, (uint8_t)*text, foreground, background, mode);
    }
    return x;
}
